    fn reading_assignable(kind: u16) -> Option<Option<u16>> {
        match kind {
            67 => Some(None),
            66 => Some(None),
            65 => Some(None),
            132 => None,
            16442 => None,
            82 => None,
            81 => None,
            20 => None,
            87 => None,
            101 => None,
            230 => None,
            228 => None,
            229 => None,
            133 => None,
            144 => None,
            _ => Some(Some(u16::MAX - 1)),
        }
    }

    fn reading_field_assignable(field: u16) -> u16 {
        match field {
            f => f,
        }
    }

